            online = event.online.toLong(),
            maxPlayers = event.maxPlayers.toLong(),
            hidePlayers = event.hidePlayers
        )
        val cancelled = session.emit(stages, payload)
        event.description = payload.description
        event.online = payload.online.coerceIn(0L, Int.MAX_VALUE.toLong()).toInt()
